from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Button, Color, Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
prime_hub = PrimeHub(top_side=Axis.Z, front_side=Axis.X)
motoEsquerda = Motor(Port.A, Direction.COUNTERCLOCKWISE)
motorDireita = Motor(Port.E, Direction.CLOCKWISE)
robo = DriveBase(motoEsquerda, motorDireita, 62, 144)
garraEsquerda = Motor(Port.D, Direction.COUNTERCLOCKWISE)
garraDireita = Motor(Port.F, Direction.CLOCKWISE)
miss_C3_A3o = 1

async def menu():
    global miss_C3_A3o
    await wait(0)
    prime_hub.display.number(miss_C3_A3o)
    motoEsquerda.control.limits(acceleration=2000)
    motorDireita.control.limits(acceleration=2000)
    robo.settings(straight_speed=400)
    robo.settings(straight_acceleration=800)
    robo.settings(turn_rate=300)
    robo.settings(turn_acceleration=500)
    if Button.LEFT in prime_hub.buttons.pressed():
        if miss_C3_A3o > 1:
            miss_C3_A3o = miss_C3_A3o - 1
        await prime_hub.speaker.beep(880, 120)
        await wait(200)
    if Button.RIGHT in prime_hub.buttons.pressed():
        if miss_C3_A3o < 8:
            miss_C3_A3o = miss_C3_A3o + 1
        await prime_hub.speaker.beep(880, 120)
        await wait(200)
    if Button.CENTER in prime_hub.buttons.pressed():
        await prime_hub.speaker.beep(784, 120)
        await prime_hub.speaker.beep(988, 120)
        await prime_hub.speaker.beep(1175, 149)
        if miss_C3_A3o == 1:
            await missao_1()
        elif miss_C3_A3o == 2:
            await _missao_2()
        elif miss_C3_A3o == 3:
            await missao_3()
        elif miss_C3_A3o == 4:
            await missao_4()
        elif miss_C3_A3o == 5:
            await missao_5()
        elif miss_C3_A3o == 6:
            await missao_6()
        elif miss_C3_A3o == 7:
            await missao_7()
        elif miss_C3_A3o == 8:
            await miss_C3_A3o8()
        else:
            pass
        await prime_hub.speaker.beep(1047, 200)
        await wait(50)
        await prime_hub.speaker.beep(1319, 200)

